import hashlib, json, re
from html.parser import HTMLParser

class AppendixHStructure(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.sections = []
        self.heading = None
        self.matches = []
        self.a8_count = 0
    def handle_starttag(self, tag, attrs):
        fields = dict(attrs)
        if tag == 'section':
            sid = fields.get('id')
            if sid == 'A8':
                self.a8_count += 1
            self.sections.append({'id': sid, 'start_line': self.getpos()[0], 'examples': 0, 'matched': False})
        classes = (fields.get('class') or '').split()
        if 'ltx_theorem_example' in classes:
            for section in self.sections:
                section['examples'] += 1
        if tag in ('h1', 'h2', 'h3', 'h4', 'h5', 'h6') and self.sections and self.heading is None:
            self.heading = {'tag': tag, 'section': self.sections[-1], 'parts': [], 'size': 0}
    def handle_startendtag(self, tag, attrs):
        self.handle_starttag(tag, attrs)
        self.handle_endtag(tag)
    def handle_data(self, data):
        if self.heading is not None and self.heading['size'] < 1024:
            take = data[:1024 - self.heading['size']]
            self.heading['parts'].append(take)
            self.heading['size'] += len(take)
    def handle_endtag(self, tag):
        if self.heading is not None and tag == self.heading['tag']:
            h = ' '.join(''.join(self.heading['parts']).split())
            section = self.heading['section']
            explicit = re.match(r'^Appendix\s+H(?:\b|\W)', h, flags=re.IGNORECASE) is not None
            a8_heading = section['id'] == 'A8' and re.match(r'^H(?:\b|\W)', h, flags=re.IGNORECASE) is not None
            if explicit or a8_heading:
                section['matched'] = True
            self.heading = None
        if tag == 'section' and self.sections:
            section = self.sections.pop()
            if section['matched']:
                self.matches.append({'section_id': section['id'], 'start_line': section['start_line'], 'closing_tag_line': self.getpos()[0], 'example_elements': section['examples']})

try:
    with open(SOURCE_PATH, 'rb') as f:
        raw = f.read()
    digest = hashlib.sha256(raw).hexdigest()
    if digest != SOURCE_SHA256:
        print(json.dumps({'state': 'SOURCE_HASH_MISMATCH', 'source_sha256': digest}))
    else:
        scanner = AppendixHStructure()
        scanner.feed(raw.decode('utf-8', errors='strict'))
        scanner.close()
        candidates = scanner.matches
        if len(candidates) != 1 or not candidates[0]['section_id']:
            state = 'ABSENT_OR_AMBIGUOUS_STOP'
        elif candidates[0]['example_elements'] != 0:
            state = 'EXAMPLE_ELEMENTS_PRESENT_STOP'
        else:
            state = 'STRUCTURAL_CANDIDATE_ONLY'
        print(json.dumps({'state': state, 'source_sha256': digest, 'source_bytes': len(raw), 'matching_sections': len(candidates), 'a8_identifier_count': scanner.a8_count, 'sections': candidates}, sort_keys=True))
except Exception as e:
    print(json.dumps({'state': 'LOCATOR_ERROR_STOP', 'error_type': type(e).__name__}, sort_keys=True))
